-- schema.sql for DuckDB\nCREATE TABLE IF NOT EXISTS price_weather (\n    date DATE,\n    commodity VARCHAR,\n    district VARCHAR,\n    state VARCHAR,\n    market VARCHAR,\n    min_price DOUBLE,\n    max_price DOUBLE,\n    modal_price DOUBLE,\n    precipitation_mm DOUBLE,\n    temp_max_c DOUBLE,\n    temp_min_c DOUBLE,\n    windspeed_kmh DOUBLE,\n    volatility_score DOUBLE,\n    volatility_label VARCHAR,\n    price_change_pct DOUBLE\n);\n\nCREATE TABLE IF NOT EXISTS weekly_aggregates (\n    week_start DATE,\n    commodity VARCHAR,\n    district VARCHAR,\n    avg_modal_price DOUBLE,\n    avg_precipitation DOUBLE,\n    avg_volatility DOUBLE,\n    max_volatility DOUBLE\n);\n\nCREATE TABLE IF NOT EXISTS alerts (\n    alert_date DATE,\n    commodity VARCHAR,\n    district VARCHAR,\n    volatility_score DOUBLE,\n    modal_price DOUBLE,\n    precipitation_mm DOUBLE,\n    alert_reason VARCHAR\n);
